window.maqAccount={loading:true,user:null,profile:null,progress:null,error:'',authMode:'login',resetMode:false};
let learningTopics=['Vapor','Clasificación de calderas','Accesorios de calderas','Combustión','Alimentación','Operación de calderas','Turbinas de vapor','Auxiliares de turbinas','Operación de turbinas','Fluido térmico','Propiedades del combustible','Circuito de combustible','Alimentación · circuito completo','Mantenimiento y fallas'];
const thermalLearningTopics=[...learningTopics];
const fmt=(n,d=2)=>Number(n||0).toLocaleString('es-AR',{minimumFractionDigits:d,maximumFractionDigits:d});
async function accountAPI(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});let data;try{data=await r.json()}catch{throw Error('No se pudo leer la respuesta del servidor.')}if(!r.ok){const e=Error(data.error||'No se pudo completar la operación.');e.status=r.status;throw e}return data}
function resetLocalAccountData(userId){window.cleanupGuided?.();window.localStudyKey=window.studyKeyFor?studyKeyFor(userId):'naval-study-v1'+(userId?':'+userId:'');try{saved={done:[],notes:{},answers:{},...JSON.parse(localStorage.getItem(window.localStudyKey)||'{}')}}catch{saved={done:[],notes:{},answers:{}}}if(typeof exam!=='undefined'){window.deferredOwnerChanged?.();window.resetFollowupSelection?.();window.examBySubject={};examAbort?.abort();window.cleanupExam?.();if(exam.blobURL)URL.revokeObjectURL(exam.blobURL);exam={...exam,history:[],messages:[],started:false,finished:false,busy:false,planToken:null,planProgress:null,blob:null,blobURL:null,error:'',reviewQueue:null,reviewItems:[],deferredMode:false,recordedAudio:null,recordedTranscript:null,exportStatus:'',followupImage:null,followupImageLoading:false,followupDraft:'',followupStatus:'',followupRequest:null}}}
async function loadAccount(){const old=maqAccount.user?.id;maqAccount.loading=true;try{const who=await accountAPI('/api/account');maqAccount.user=who.user;maqAccount.profile=who.profile;maqAccount.error=''}catch(e){maqAccount.user=null;maqAccount.profile=null;maqAccount.error=e.status===401?maqAccount.error:e.message}if(maqAccount.user){const subject=currentSubject;try{const p=await accountAPI('/api/progress?subject='+encodeURIComponent(subject));if(subject===currentSubject)maqAccount.progress=p}catch(e){maqAccount.progress=null;maqAccount.error=e.message}}else maqAccount.progress=null;maqAccount.loading=false;if(old!==maqAccount.user?.id)resetLocalAccountData(maqAccount.user?.id);updateAccountUI();if(['cuenta','usuarios','progreso','profesor','oral'].includes(location.hash.slice(1)))render()}
function updateAccountUI(){const b=document.querySelector('#account-badge');if(b){b.textContent=maqAccount.loading?'Conectando…':maqAccount.user?(maqAccount.profile?.full_name||maqAccount.user.email):'Ingresar / Registrarse';b.href='#cuenta'}const n=document.querySelector('#users-nav');if(n)n.hidden=maqAccount.profile?.role!=='admin';refreshProgressUI()}
function progressMarkup(){const a=maqAccount,p=a.progress;if(a.loading)return '<div class="learning-progress account-message">Conectando tu cuenta y progreso…</div>';if(!a.user)return `<div class="learning-progress account-message"><strong>Tu progreso empieza con tu cuenta.</strong><p>Ingresá o registrate para conservar intentos, notas y evolución por tema.</p><a class="button" href="#cuenta">Ingresar / Registrarme →</a>${a.error?'<p role="alert">'+esc(a.error)+'</p>':''}</div>`;if(!p)return '<div class="learning-progress account-message">No se pudo cargar el progreso. <button class="text-button" onclick="loadAccount()">Reintentar</button></div>';return `<section class="learning-progress"><div class="progress-title"><div><span class="eyebrow">TU PROGRESO GUARDADO</span><h3>Un tema a la vez.</h3></div><strong>${fmt(p.mastery)}<small>%</small></strong></div><progress class="sr-only" max="100" value="${Number(p.mastery)||0}" aria-label="Progreso global"></progress><div class="topic-track">${learningTopics.map((name,i)=>{const t=p.topics?.find(t=>t.topic===i)||{};return `<div class="topic-piece" tabindex="0" style="--mastery:${Math.max(0,Math.min(100,t.mastery||0))}%" title="${i+1}. ${esc(name)} · Dominio ${fmt(t.mastery)}% · ${t.attempts||0} intentos · Aciertos ${fmt(t.accuracy,1)}% · Promedio ${fmt(t.average)}/10"><span>${i+1}</span><div class="topic-tooltip"><strong>${i+1}. ${esc(name)}</strong><p>Dominio: ${fmt(t.mastery)}% · ${t.attempts||0} intentos<br>Aciertos: ${fmt(t.accuracy,1)}% · Promedio: ${fmt(t.average)}/10</p></div></div>`}).join('')}</div><div class="progress-totals"><span>${p.practicedQuestions||0} / ${p.totalQuestions||118} preguntas practicadas</span><span>${p.attempts||0} intentos</span><span>Aciertos ${fmt(p.accuracy,1)}%</span><span>Promedio ${fmt(p.average)} / 10</span><a href="#progreso">Ver mi historial ↗</a></div><p class="progress-explain">El avance usa tu mejor nota en cada pregunta; las no intentadas cuentan cero. Acierto = nota final de 7/10 o más. Pasá por cada tramo para ver el tema y sus resultados.</p></section>`}
function refreshProgressUI(){const target=document.querySelector('#learning-progress');if(target)target.innerHTML=progressMarkup()}
function questionStatsMarkup(meta,fallback){if(!meta)return '';const s=maqAccount.progress?.questions?.find(q=>q.question_id===meta.id)||fallback||{};return `<div class="question-history"><strong>${esc(learningTopics[meta.topic]||'Tema de práctica')}</strong><span>Lo intentaste ${s.attempts||0} ${s.attempts===1?'vez':'veces'} · Aciertos ${fmt(s.accuracy,1)}% · Promedio ${fmt(s.average)} / 10</span></div>`}
function comparisonMarkup(c){if(!c)return '';return `<div class="real-comparison"><strong>Comparación con tu historial guardado</strong><div class="comparison-grid"><span>Este examen<b>${fmt(c.examAverage)} / 10</b><small>${c.examAttempts} respuestas · ${fmt(c.examAccuracy,1)}% de aciertos</small></span><span>Antes de este examen<b>${c.previousAttempts?fmt(c.previousAverage)+' / 10':'Sin historial'}</b><small>${c.previousAttempts} intentos anteriores</small></span><span>Avance global<b>${fmt(c.previousMastery)}% → ${fmt(c.currentMastery)}%</b><small>${c.averageDelta===null?'Primera referencia para comparar':(c.averageDelta>=0?'+':'')+fmt(c.averageDelta)+' puntos frente al promedio previo'}</small></span></div><p>La comparación es orientativa: los temas y niveles de exigencia pueden variar.${c.examAttempts<3?' Esta muestra es pequeña.':''}</p></div>`}
function renderAccount(){const a=maqAccount;if(a.loading){app.innerHTML=head('TU CUENTA','Conectando…','Estamos recuperando tu sesión.');return}if(a.user){app.innerHTML=head('TU CUENTA','Tu espacio de estudio.',a.profile?.full_name||a.user.email)+`<section class="account-card"><span class="tag">${a.profile?.role==='admin'?'ADMINISTRADOR':'ALUMNO'}</span><h2>${esc(a.profile?.full_name||'Mi cuenta')}</h2><p>${esc(a.user.email)}</p><div class="actions"><a class="button" href="${'#profesor'}">${'Practicar con el profesor →'}</a>${'<a class="button secondary" href="#progreso">Ver mi progreso</a>'}${a.profile?.role==='admin'?'<a class="button secondary" href="#usuarios">Gestionar usuarios</a>':''}<button id="logout" class="secondary">Cerrar sesión</button></div><p class="source">Tu historial se guarda en tu cuenta de Supabase y está separado del de otros alumnos.</p></section>${a.resetMode?'<section class="account-card"><h3>Elegí una nueva contraseña</h3><form id="reset-form"><label for="new-password">Nueva contraseña</label><input id="new-password" type="password" minlength="8" maxlength="128" autocomplete="new-password" required><button>Guardar nueva contraseña</button><p id="reset-message" role="status"></p></form></section>':''}`;document.querySelector('#logout').onclick=async()=>{await accountAPI('/api/account',{action:'logout'});await loadAccount()};if(a.resetMode)document.querySelector('#reset-form').onsubmit=async e=>{e.preventDefault();try{await accountAPI('/api/account',{action:'updatePassword',password:document.querySelector('#new-password').value});a.resetMode=false;renderAccount()}catch(err){document.querySelector('#reset-message').textContent=err.message}};return}const register=a.authMode==='register',recover=a.authMode==='recover';app.innerHTML=head('USUARIOS Y PROGRESO',register?'Creá tu cuenta.':recover?'Recuperá tu acceso.':'Volvé a tu cuaderno.','Cada alumno conserva su propio historial de preguntas, notas y evolución.')+`<section class="account-card auth-card"><a class="button google-button" href="/api/oauth">G · Ingresar con Google</a><div class="auth-divider">o con tu correo</div><form id="auth-form">${register?'<label for="auth-name">Nombre</label><input id="auth-name" type="text" maxlength="100" autocomplete="name" required>':''}<label for="auth-email">Correo</label><input id="auth-email" type="email" maxlength="254" autocomplete="email" required>${!recover?'<label for="auth-password">Contraseña</label><input id="auth-password" type="password" minlength="8" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'" required>':''}<button id="auth-submit">${register?'Registrarme':recover?'Enviar enlace':'Ingresar'}</button><p id="auth-message" class="auth-message" role="status">${esc(a.error||'')}</p></form><div class="auth-options"><button class="text-button" id="auth-switch">${register?'Ya tengo cuenta':'Crear una cuenta'}</button><button class="text-button" id="auth-recover">Olvidé mi contraseña</button></div><p class="source">Podés registrarte directamente con Google o pedir un alta al administrador. El registro y la recuperación por correo requieren confirmación y un servicio de envío configurado.</p></section>`;document.querySelector('#auth-switch').onclick=()=>{a.authMode=register?'login':'register';a.error='';renderAccount()};document.querySelector('#auth-recover').onclick=()=>{a.authMode='recover';a.error='';renderAccount()};document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const b=document.querySelector('#auth-submit');b.disabled=true;const m=document.querySelector('#auth-message');m.textContent='Conectando…';try{const result=await accountAPI('/api/account',{action:register?'register':recover?'recover':'login',email:document.querySelector('#auth-email').value,password:document.querySelector('#auth-password')?.value,name:document.querySelector('#auth-name')?.value});if(result.message){m.textContent=result.message;b.disabled=false}else{await loadAccount();if(maqAccount.user)location.hash='profesor'}}catch(err){m.textContent=err.message;b.disabled=false}}}
async function renderUsers(){app.innerHTML=head('ADMINISTRACIÓN','Usuarios de la aplicación.','Agregá alumnos con una contraseña inicial propia para cada cuenta.');if(maqAccount.loading){app.innerHTML+='<p>Conectando…</p>';return}if(maqAccount.profile?.role!=='admin'){app.innerHTML+='<div class="note">Esta sección requiere una cuenta administradora. <a href="#cuenta">Ingresar</a></div>';return}app.innerHTML+=`<section class="account-card"><h3>Agregar alumno</h3><form id="new-user-form" class="new-user-form"><label>Nombre<input name="name" maxlength="100" autocomplete="off" required></label><label>Correo<input name="email" type="email" maxlength="254" autocomplete="off" required></label><label>Contraseña inicial<input name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></label><button>Agregar usuario</button></form><p id="users-message" role="status"></p></section><div id="users-list"></div>`;async function list(){try{const d=await accountAPI('/api/users');document.querySelector('#users-list').innerHTML='<div class="user-table">'+d.users.map(u=>`<article><strong>${esc(u.full_name||'Sin nombre')}</strong><span>${esc(u.email)}</span><small>${u.role==='admin'?'Administrador':'Alumno'}</small></article>`).join('')+'</div>'}catch(e){document.querySelector('#users-list').textContent=e.message}}document.querySelector('#new-user-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button');button.disabled=true;try{await accountAPI('/api/users',Object.fromEntries(new FormData(f)));f.reset();document.querySelector('#users-message').textContent='Alumno creado.';await list()}catch(err){document.querySelector('#users-message').textContent=err.message}finally{button.disabled=false}};await list()}
async function renderProgressPage(){const requestedSubject=currentSubject;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#progreso'));app.innerHTML=head('EVOLUCIÓN PERSONAL','Tu historial de aprendizaje.','Resultados guardados en tu cuenta, por tema y por pregunta.')+'<div id="learning-progress">'+progressMarkup()+'</div>';if(!maqAccount.user)return;const p=maqAccount.progress;app.innerHTML+=`<div class="section-head"><h2>Preguntas practicadas</h2></div><div class="question-results">${p?.questions?.length?p.questions.map(q=>`<article><strong>${esc(learningTopics[q.topic])} · ${esc(studyQuestionLabel(q.question_id))}</strong><p>${q.attempts} intentos · Aciertos ${fmt(q.accuracy,1)}% · Promedio ${fmt(q.average)}/10 · Mejor nota ${fmt(q.best)}/10</p></article>`).join(''):'<p>Todavía no hay intentos guardados. Empezá una práctica con el profesor.</p>'}</div><div class="section-head"><h2>Últimos exámenes finalizados</h2></div><div id="recent-exams">Cargando…</div>`;try{const d=await accountAPI('/api/progress?history=1&subject='+encodeURIComponent(currentSubject));if(requestedSubject!==currentSubject||!document.querySelector('#recent-exams'))return;document.querySelector('#recent-exams').innerHTML=d.sessions?.length?d.sessions.map(s=>`<details class="past-exam"><summary>${esc(learningTopics[s.topic]||'Integrador')} · ${new Date(s.finished_at).toLocaleDateString('es-AR')} · ${fmt(s.summary?.score)}/10</summary><p>${esc(s.summary?.feedbackSpeech||s.summary?.speech||'')}</p><p>${esc(s.summary?.feedback||'')}</p>${comparisonMarkup(s.summary?.comparison)}</details>`).join(''):'<p>No hay exámenes finalizados todavía.</p>'}catch(e){document.querySelector('#recent-exams').textContent=e.message}}
document.addEventListener('DOMContentLoaded',async()=>{const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('access_token')){try{maqAccount.resetMode=fragment.get('type')==='recovery';await accountAPI('/api/account',{action:'accept',access_token:fragment.get('access_token'),refresh_token:fragment.get('refresh_token')});history.replaceState(null,'',location.pathname+'#cuenta')}catch(e){maqAccount.error=e.message}}const query=new URLSearchParams(location.search);if(query.has('login_error')){maqAccount.error=query.get('login_error');history.replaceState(null,'',location.pathname+'#cuenta')}await loadAccount()});
